    - {round: 12, action: "Consider adding Recht et al. (2019), Ye et al. (2024) Data Contamination Quiz if space permits", assigned_to: "paper_agent", status: "open"}

- id: "R4-W6"
  summary: "Abstract numeric density too high"
  category: writing
  severity: warning
  status: open
