    - {round: 7, reviewers: "", note: "Abstract rewritten. Resolved."}
    - {round: 12, reviewers: "R1,R2", note: "CONSENSUS Should-Fix. Re-raised and reopened. R2-W2: Abstract contains ~25+ specific numbers, core message buried. R1 agrees. Both suggest limiting to 3-5 most critical numbers."}
  action_items:
    - {round: 12, action: "Reduce Abstract numeric density to 3-5 key numbers; move remaining details to main text", assigned_to: "paper_agent", status: "open"}

- id: "R3-N7"
  summary: "Technical novelty limited — 2PL+γ is standard explanatory IRT/DIF"
  category: framing
  severity: critical
  status: in_progress
