- id: "R6-W1"
  summary: "SFT AUGMENT mode volume confound"
  category: experiment
  severity: critical
  status: in_progress
  first_raised_round: 6
  last_seen_round: 12
  mentions:
    - {round: 6, reviewers: "R1,R2", note: "AUGMENT vs REPLACE not specified."}
    - {round: 10, reviewers: "R1,R2", note: "d000=50k, d100≈66.5k (+33.1%). Should-Fix."}
    - {round: 11, reviewers: "R1,R2", note: "CONSENSUS Must-Fix. Data-quantity control most critical missing experiment."}
    - {round: 12, reviewers: "R1,R2", note: "CONSENSUS Should-Fix. Volume control on Falcon3 (Appendix Q) decomposes Benefit into 45% volume + 55% content. R1-W2: at least one non-Benefit family needs volume control (especially Collapse). R2-W1: if Qwen-14B also collapses with non-benchmark MCQ, it's catastrophic forgetting not contamination-specific. Volume control now exists for one family but generalizability unverified. Training set sizes per dosage now reported in §4.1."}
  action_items:
    - {round: 6, action: "Clarify SFT injection protocol", assigned_to: "paper_agent", status: "done"}
    - {round: 10, action: "Report training set sizes per dosage", assigned_to: "paper_agent", status: "done"}
    - {round: 11, action: "Add data-quantity control or replacement design", assigned_to: "main_agent", status: "in_progress"}
