- id: "R8-W3"
  summary: "Algorithm 1 threshold τ=2pp lacks theoretical basis"
  category: method
  severity: warning
  status: in_progress
  first_raised_round: 8
  last_seen_round: 12
  mentions:
    - {round: 8, reviewers: "R2,R1", note: "30/30 pass too coarse."}
    - {round: 10, reviewers: "R1,R2", note: "Appendix includes nearest-transition analysis. Minor."}
    - {round: 11, reviewers: "R1,R2", note: "DIVERGENT: R1 Major, R2 Critical. τ=2pp definitional not empirical."}
    - {round: 12, reviewers: "R1,R2", note: "CONSENSUS Should-Fix. R1-W4: τ=2pp based on n=3 cross-seed SD which is itself unstable. Grid sweep proves data well-separated, not that τ is correct. R2 agrees. Both recommend permutation-based null distribution or explicit classification as descriptive heuristic."}
  action_items:
    - {round: 8, action: "Add threshold sensitivity heatmap", assigned_to: "paper_agent", status: "open"}
    - {round: 11, action: "Report Immune/Benefit boundary sensitivity to τ∈[1,3]pp", assigned_to: "paper_agent", status: "done"}
